            const multi = $.let(State.bind([BooleanType], "ex.zone.multi", true));
            const multiOn = $.let(multi.read());
            const onMulti = $.const(
                East.function([BooleanType], NullType, ($, v) => {
                    $(multi.write(v));
                }),
            );
