    const encoder = $.let(Sklearn.ordinalEncoderFit(X_categorical));
    const X_encoded = $.let(Sklearn.ordinalEncoderTransform(encoder, X_categorical));

    // Shape preserved: 4 samples × 2 features, values now 0-indexed
